import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.LinkedHashSet;
import java.util.Set;

public class TallyGate {
    public static int tint_span(Path exploded, Path roster, Path jar) throws Exception {
        if (!Files.isRegularFile(jar)) {
            return 1;
        }
        Set<String> wanted = new LinkedHashSet<String>();
        for (String line : Files.readAllLines(roster)) {
            String s = line.trim();
            if (s.isEmpty()) {
                continue;
            }
            String[] fields = s.split("\\s+");
            if (fields.length < 2) {
                return 1;
            }
            wanted.add(fields[0]);
        }

        String java = Paths.get(System.getProperty("java.home"), "bin", "java").toString();
        Process p = new ProcessBuilder(java, "-cp", jar.toString(), "Main", "booth")
            .redirectErrorStream(true).start();
        Set<String> actual = new LinkedHashSet<String>();
        try (BufferedReader in = new BufferedReader(new InputStreamReader(p.getInputStream()))) {
            String line;
            while ((line = in.readLine()) != null) {
                actual.add(line.trim());
            }
        }
        int rc = p.waitFor();
        return rc == 0 && actual.containsAll(wanted) ? 0 : 1;
    }

    public static void main(String[] args) throws Exception {
        System.exit(tint_span(
            Paths.get("/app/blastcp"),
            Paths.get("/app/desknote/NAMES.txt"),
            Paths.get("/app/jarwell/husk.jar")));
    }
}
